// @ts-check
// Injects the four example diagrams (one per type) into the first kafka
// milestone. The fixture is generated by the compiler itself
// (aggregator TestDiagramaFixturesGolden), so the figures and the JSON here
// are exactly what a real milestone with diagrams ships.
const fixture = require('../fixtures/diagramas.json');

const SLUG = 'kafka';
const IDS = ['exemplo-topologia', 'exemplo-sequencia', 'exemplo-estados', 'exemplo-fluxo', 'exemplo-grafico', 'exemplo-animado'];

/** @param {import('@playwright/test').Page} page */
async function injectDiagramas(page) {
  let firstId = '';
  await page.route(`**/data/courses/${SLUG}.json`, async (route) => {
    const resp = await route.fetch();
    const course = await resp.json();
    const m = course.milestones[0];
    firstId = m.id;
    const figures = IDS.map((id) => fixture.figures[id]).join('');
    const prose = m.sections.find((/** @type {any} */ s) => s.kind === 'prose');
    prose.html += figures;
    m.html += figures;
    await route.fulfill({ response: resp, json: course });
  });
  await page.route(`**/data/diagramas/${SLUG}.json`, (route) => route.fulfill({ json: fixture.diagramas }));
  return { slug: SLUG, ids: IDS, firstId: () => firstId };
}

module.exports = { injectDiagramas, SLUG, IDS };
